public interface ICoffee
{
    decimal Cost();
    string Description();
}

public class SimpleCoffee : ICoffee
{
    public decimal Cost() => 2.0m;
    public string Description() => "Simple coffee";
}

public class MilkDecorator : ICoffee
{
    private readonly ICoffee _coffee;

    public MilkDecorator(ICoffee coffee)
    {
        _coffee = coffee;
    }

    public decimal Cost() => _coffee.Cost() + 0.5m;
    public string Description() => _coffee.Description() + ", milk";
}

public class SugarDecorator : ICoffee
{
    private readonly ICoffee _coffee;

    public SugarDecorator(ICoffee coffee)
    {
        _coffee = coffee;
    }

    public decimal Cost() => _coffee.Cost() + 0.25m;
    public string Description() => _coffee.Description() + ", sugar";
}
